DO $test$
DECLARE viewer uuid; peer uuid; venue uuid; obj uuid:=gen_random_uuid(); path text; rows jsonb;
BEGIN
 SELECT p.user_id INTO viewer FROM public.profiles p WHERE NOT EXISTS(SELECT 1 FROM public.user_roles r WHERE r.user_id=p.user_id) AND NOT public.is_user_banned(p.user_id) LIMIT 1;
 SELECT p.user_id INTO peer FROM public.profiles p WHERE p.user_id<>viewer AND NOT public.is_user_banned(p.user_id) LIMIT 1;
 SELECT id INTO venue FROM public.cafes LIMIT 1;
 IF viewer IS NULL OR peer IS NULL OR venue IS NULL THEN RAISE EXCEPTION 'Two profiles and one venue required'; END IF;
 IF has_function_privilege('authenticated','public.authorize_current_cafe_photo(uuid,uuid,text)','EXECUTE') OR has_function_privilege('anon','public.list_current_cafe_profiles(uuid)','EXECUTE') THEN RAISE EXCEPTION 'Permission widening'; END IF;
 path:=peer::text||'/'||obj::text||'.webp';
 PERFORM set_config('request.jwt.claims',json_build_object('sub',viewer,'role','service_role')::text,true);
 UPDATE public.profiles SET is_visible=true WHERE user_id IN(viewer,peer);
 DELETE FROM public.user_blocks WHERE (blocker_id=viewer AND blocked_id=peer) OR (blocker_id=peer AND blocked_id=viewer);
 INSERT INTO storage.objects(id,bucket_id,name,owner_id,metadata) VALUES(obj,'avatars',path,peer::text,'{"mimetype":"image/webp","size":16}');
 UPDATE public.profiles SET photo_url='avatar:'||path,photo_urls=ARRAY['avatar:'||path] WHERE user_id=peer;
 PERFORM public.record_photo_review(peer,path,obj,'accepted');
 DELETE FROM public.check_ins WHERE user_id IN(viewer,peer);
 IF public.authorize_current_cafe_photo(viewer,venue,path) IS NOT NULL THEN RAISE EXCEPTION 'No checkin accepted'; END IF;
 INSERT INTO public.check_ins(user_id,cafe_id,check_in_time,expiry_time,last_active_at) VALUES(viewer,venue,clock_timestamp(),clock_timestamp()+interval '1 hour',clock_timestamp()),(peer,venue,clock_timestamp(),clock_timestamp()+interval '1 hour',clock_timestamp());
 IF public.authorize_current_cafe_photo(viewer,venue,path) IS DISTINCT FROM obj THEN RAISE EXCEPTION 'Same venue photo denied'; END IF;
 PERFORM set_config('request.jwt.claims',json_build_object('sub',viewer,'role','authenticated')::text,true);
 rows:=public.list_current_cafe_profiles(venue);
 IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(rows) x WHERE x->>'user_id'=peer::text AND x->'photo_refs' ? ('avatar:'||path)) THEN RAISE EXCEPTION 'Photo projection missing'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(rows) x WHERE x ?| ARRAY['email','phone','date_of_birth','verification_selfie_url','verification_requested_at']) THEN RAISE EXCEPTION 'Private field leaked'; END IF;
 UPDATE public.check_ins SET check_in_time=(SELECT enabled_at FROM private.cafe_photo_release)-interval '1 second' WHERE user_id=peer;
 IF public.authorize_current_cafe_photo(viewer,venue,path) IS NOT NULL THEN RAISE EXCEPTION 'Old checkin consent bypass'; END IF;
 UPDATE public.check_ins SET check_in_time=clock_timestamp() WHERE user_id=peer;
 INSERT INTO public.user_blocks(blocker_id,blocked_id) VALUES(peer,viewer);
 IF public.authorize_current_cafe_photo(viewer,venue,path) IS NOT NULL OR EXISTS(SELECT 1 FROM jsonb_array_elements(public.list_current_cafe_profiles(venue)) x WHERE x->>'user_id'=peer::text) THEN RAISE EXCEPTION 'Blocked visibility'; END IF;
 DELETE FROM public.user_blocks WHERE blocker_id=peer AND blocked_id=viewer;
 UPDATE public.profiles SET is_visible=false WHERE user_id=peer;
 IF public.authorize_current_cafe_photo(viewer,venue,path) IS NOT NULL THEN RAISE EXCEPTION 'Hidden profile visible'; END IF;
 UPDATE public.profiles SET is_visible=true WHERE user_id=peer;
 UPDATE private.photo_reviews SET verdict='rejected' WHERE object_path=path;
 IF public.authorize_current_cafe_photo(viewer,venue,path) IS NOT NULL THEN RAISE EXCEPTION 'Rejected photo visible'; END IF;
 UPDATE private.photo_reviews SET verdict='accepted' WHERE object_path=path;
 UPDATE storage.objects SET id=gen_random_uuid() WHERE id=obj;
 IF public.authorize_current_cafe_photo(viewer,venue,path) IS NOT NULL THEN RAISE EXCEPTION 'Recreated object visible'; END IF;
 UPDATE storage.objects SET id=obj WHERE name=path AND bucket_id='avatars';
 UPDATE public.check_ins SET expiry_time=now()-interval '1 second' WHERE user_id=viewer;
 IF public.authorize_current_cafe_photo(viewer,venue,path) IS NOT NULL OR public.list_current_cafe_profiles(venue)<>'[]'::jsonb THEN RAISE EXCEPTION 'Expired viewer access'; END IF;
 UPDATE public.check_ins SET expiry_time=now()+interval '1 hour' WHERE user_id=viewer;
 UPDATE public.check_ins SET expiry_time=now()-interval '1 second' WHERE user_id=peer;
 IF public.authorize_current_cafe_photo(viewer,venue,path) IS NOT NULL THEN RAISE EXCEPTION 'Expired target access'; END IF;
 IF public.authorize_current_cafe_photo(viewer,gen_random_uuid(),path) IS NOT NULL THEN RAISE EXCEPTION 'Wrong venue access'; END IF;
END $test$;
ROLLBACK;
SELECT 'Same-venue photos: consent cutoff, active attendance, limited fields, block/privacy, rejected/stale objects, expired viewer/target and RPC grants passed; all writes rolled back' AS result;
